<?php require '../config/db.php'; $message = ''; if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $name = trim($_POST['name'] ?? ''); $email = strtolower(trim($_POST['email'] ?? '')); $password = $_POST['password'] ?? ''; if ($name === '' || strlen($name) > 120 || strlen($email) > 190 || !filter_var($email, FILTER_VALIDATE_EMAIL)) { $message = 'Enter a valid name and email address.'; } elseif (strlen($password) < 8) { $message = 'Password must be at least 8 characters.'; } else { try { $stmt = $pdo->prepare('INSERT INTO users (name, email, password, role) VALUES (?, ?, ?, ?)'); $stmt->execute([$name, $email, password_hash($password, PASSWORD_DEFAULT), 'customer']); header('Location: login.php?registered=1'); exit; } catch (PDOException $exception) { if ($exception->getCode() === '23000') { $message = 'An account with that email already exists.'; } else { throw $exception; } } } } ?> <!DOCTYPE html> <html lang="en"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1"> <title>Create Account | Bake Me Happy</title> <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"> <style> *{box-sizing:border-box} body{ margin:0;min-height:100vh; background:url('https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=1600&q=80') center/cover no-repeat fixed; display:grid;place-items:center;padding:20px; font-family:system-ui;position:relative;overflow:hidden; } body::before{content:'';position:fixed;inset:0;background:rgba(0,0,0,.25);z-index:0} /* --- WORDS ON THE PICTURE --- */ .brand{position:fixed;top:24px;left:28px;z-index:2;color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.8);display:flex;align-items:center;gap:12px} .brand img{width:64px;height:64px;object-fit:contain;border-radius:50%} .brand small{display:block;font-weight:700;letter-spacing:.25em;font-size:.65rem;color:#ffcf9e} .brand b{font-size:1.15rem} .quote-left{position:fixed;left:28px;bottom:28px;z-index:2;color:#fff;max-width:320px;text-shadow:0 2px 12px rgba(0,0,0,.8)} .quote-left h2{font-size:2.1rem;line-height:1.05;font-weight:800;margin:0} .quote-left p{opacity:.9;margin:8px 0 0} .quote-right{position:fixed;right:28px;bottom:28px;z-index:2;color:#fff;text-align:right;text-shadow:0 2px 12px rgba(0,0,0,.8)} .quote-right b{display:block;font-size:1.1rem} .quote-right span{font-size:.85rem;opacity:.9} .tag-top{position:fixed;right:28px;top:26px;z-index:2;color:#fff;background:rgba(0,0,0,.35);backdrop-filter:blur(8px);padding:8px 14px;border-radius:999px;font-size:.8rem;font-weight:600;border:1px solid rgba(255,255,255,.3)} /* --- SAME BLURRY CARD AS LOGIN --- */ .card-blur{ position:relative;z-index:1; width:min(100%,440px); padding:34px 30px; background:rgba(255,255,255,.45); backdrop-filter:blur(28px) saturate(140%); -webkit-backdrop-filter:blur(28px) saturate(140%); border:1px solid rgba(255,255,255,.55); border-radius:20px; box-shadow:0 20px 60px rgba(0,0,0,.45); } .card-blur h1{font-size:2rem;font-weight:800;margin:6px 0 4px;color:#1c1917} .eyebrow{letter-spacing:.2em;color:#9a3412;font-weight:800;font-size:.72rem} input.form-control{padding:13px 14px;border-radius:12px;background:rgba(255,255,255,.75);border:1px solid rgba(255,255,255,.8)} .btn-bake{background:#c2410c;border:none;padding:13px;border-radius:12px;font-weight:700;width:100%;color:#fff} .btn-bake:hover{background:#9a3412;color:#fff} a{color:#9a3412;font-weight:700;text-decoration:none} @media(max-width:900px){.quote-left,.quote-right,.tag-top{display:none}} </style> </head> <body> <!-- WORDS RELATED TO THE CAKE PICTURE --> <div class="brand"> <img src="/EL3/assets/bake-me-happy-logo.png" alt="Bake Me Happy logo"> <div><small>BAKE ME HAPPY • FRESHLY BAKED CAKES</small><b>Bake Me Happy</b></div> </div> <div class="tag-top">🍰 Freshly baked cakes today</div> <div class="quote-left"> <h2>Sweet cakes,<br>made for you.</h2> <p>Join us and get your favorite cakes soft, sweet, and fresh from the oven.</p> </div> <div class="quote-right"> <b>Sweet. Soft. Homemade.</b> <span>Baked fresh daily • Made with love</span> </div> <!-- BLURRY CARD --> <main class="card-blur"> <div class="eyebrow">CREATE ACCOUNT</div> <h1>Join us</h1> <p style="color:#44403c">Join Bake Me Happy to browse and order fresh cakes.</p> <?php if ($message !== ''): ?><div class="alert alert-danger" role="alert"><?= h($message) ?></div><?php endif; ?> <form method="POST" action="register.php"> <input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"> <div class="mb-3"> <label for="name" class="form-label fw-semibold">Full name</label> <input id="name" name="name" type="text" class="form-control" maxlength="120" placeholder="Juan Dela Cruz" autocomplete="name" required> </div> <div class="mb-3"> <label for="email" class="form-label fw-semibold">Email</label> <input id="email" name="email" type="email" class="form-control" maxlength="190" placeholder="juandelacruz@gmail.com" autocomplete="email" required> </div> <div class="mb-3"> <label for="password" class="form-label fw-semibold">Password</label> <input id="password" name="password" type="password" class="form-control" minlength="8" placeholder="At least 8 characters" autocomplete="new-password" required> <div class="form-text">Use at least 8 characters.</div> </div> <button class="btn-bake">Create account</button> </form> <p class="mt-3 mb-0 text-center">Already registered? <a href="login.php">Sign in</a></p> </main> </body> </html>